let orders = $json.orders_json;
if (typeof orders === 'string') orders = JSON.parse(orders);
orders = Array.isArray(orders) ? orders : [];
const date = new Intl.DateTimeFormat('es-ES', { timeZone: 'Europe/Madrid' }).format(new Date());
const sections = orders.map((order) => `#${order.order_id} — ${order.customer_name}
${order.address}
Tel: ${order.phone}
${order.items}
Total: ${order.total} €`);
const message = sections.length
  ? `PEDIDOS CONFIRMADOS — ${date}

${sections.join('

')}`
  : `PEDIDOS CONFIRMADOS — ${date}

No hay pedidos confirmados.`;
return [{ json: { ok: true, count: orders.length, message, orders } }];
